catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    try {
        var vendor_name = g_form.getValue('vendor_csr');
        if (vendor_name === 'Azure') {
            var cmdb_sync = g_form.getValue('cmdb_sync');
            var device_name = g_form.getValue('device_name_csr');
            var company_name = g_form.getValue('company_name');
            var ga = new GlideAjax('get_keyvault_names');
            ga.addParam("sysparm_name", "getProfileNames");
            ga.addParam("sysparm_vendorName", vendor_name);
            ga.addParam("sysparm_deviceName", device_name);
            ga.addParam("sysparm_company", company_name);
            ga.getXML(getResponse);
        }
    } catch (error) {
        g_form.addErrorMessage("Error while fetching the key_vault_name: " + error);
        var message = 'Error occured while setting profile names for the push - ' + error;
        ga = new GlideAjax('avx_logger');
        ga.addParam("sysparm_name", "avxLogger");
        ga.addParam("sysparm_level", "Error");
        ga.addParam("sysparm_script", "set_key_vault_name");
        ga.addParam("sysparm_application", "AppViewX");
        ga.addParam("sysparm_message", message);
        ga.getXML(function() {});
    }

    function getResponse(response) {
        try {
            g_form.clearValue('key_vault_name');
            g_form.clearOptions('key_vault_name');
            g_form.setMandatory('key_vault_name', true);
            g_form.setDisplay('key_vault_name', true);
            var iterator;
            var res = response.responseXML.documentElement.getAttribute('answer');
            try {
                res = JSON.parse(res);
            } catch (err) {
                throw res || "Couldn't parse the response while trying to get key_vault_name.";
            }

            g_form.addOption('key_vault_name', '', 'Select');
            if (!res.response.objects) {
                throw "Error while getting the response from the AppViewX for the Key vault Name " + JSON.stringify(res);
            }
            var profile_list = res.response.objects;
            if (profile_list.length == 0) {
                throw "There is no Key Vaults available for the selected device " + device_name;
            }
            for (iterator = 0; iterator < profile_list.length; iterator++) {
                g_form.addOption('key_vault_name', profile_list[iterator], profile_list[iterator]);
            }

        } catch (error) {
            g_form.addErrorMessage("Error while fetching the key_vault_name: " + error);
            var message = 'Error occured while fetching the key_vault_name - ' + error;
            var ga = new GlideAjax('avx_logger');
            ga.addParam("sysparm_name", "avxLogger");
            ga.addParam("sysparm_level", "Error");
            ga.addParam("sysparm_script", "set_key_vault_name");
            ga.addParam("sysparm_application", "AppViewX");
            ga.addParam("sysparm_message", message);
            ga.getXML(function() {});
        }
    }
}
